    "v2.payment.generate_income_statement": {
      "path": "/api/v2/payment/generate_income_statement",
      "method": "GET",
      "risk": "W",
      "identity": "Shop",
      "description": "payment: generate income statement",
      "input_schema": {
        "type": "object",
        "properties": {
          "release_time_from": {
            "anyOf": [
              {
                "type": "integer",
                "minimum": -9007199254740991,
                "maximum": 9007199254740991
              },
              {
                "type": "string",
                "pattern": "^-?(0|[1-9][0-9]{0,18})$"
              }
            ],
            "x-integer": "int64",
            "description": "The release_time_from must be - Monday (local time) for a weekly report - The 1st day (local time) of a Month for a monthly report"
          },
          "release_time_to": {
            "anyOf": [
              {
                "type": "integer",
                "minimum": -9007199254740991,
                "maximum": 9007199254740991
              },
              {
                "type": "string",
                "pattern": "^-?(0|[1-9][0-9]{0,18})$"
              }
            ],
            "x-integer": "int64",
            "description": "The release_time_to must be - Sunday (local time) for a weekly report - The last day (local time) of a Month for a monthly report"
          },
          "statement_type": {
            "type": "integer",
            "minimum": -2147483648,
            "maximum": 2147483647,
            "description": "STATEMENT_TYPE_WEEKLY = 1; STATEMENT_TYPE_MONTHLY = 2; Local seller Income statement requires this value to be set. CB seller income statement does not require this."
          }
        },
        "required": [
          "release_time_from",
          "release_time_to",
          "statement_type"
        ],
        "additionalProperties": false,
        "description": "v2.payment.generate_income_statement\nTrigger income statement generation.\nAuthorization: Shop; existing bound shop and Seller In House System app. Platform market, enrollment and method permissions still apply."
      },
      "output_schema": {
        "type": "object",
        "properties": {
          "response": {
            "type": "object",
            "properties": {
              "id": {
                "anyOf": [
                  {
                    "type": "integer",
                    "minimum": -9007199254740991,
                    "maximum": 9007199254740991
                  },
                  {
                    "type": "string",
                    "pattern": "^-?(0|[1-9][0-9]{0,18})$"
                  }
                ],
                "x-integer": "int64",
                "description": "Identifier of income statement file."
              }
            },
            "additionalProperties": true
          },
          "error": {
            "type": "string",
            "description": "error code"
          },
          "message": {
            "type": "string",
            "description": "error message"
          }
        },
        "additionalProperties": true
      }
    },
    "v2.payment.get_income_statement": {
      "path": "/api/v2/payment/get_income_statement",
      "method": "GET",
      "risk": "R",
      "identity": "Shop",
      "description": "payment: get income statement",
      "input_schema": {
        "type": "object",
        "properties": {
          "income_statement_id": {
            "anyOf": [
              {
                "type": "integer",
                "minimum": -9007199254740991,
                "maximum": 9007199254740991
              },
              {
                "type": "string",
                "pattern": "^-?(0|[1-9][0-9]{0,18})$"
              }
            ],
            "x-integer": "int64",
            "description": "The identifier for income statement file request. return from the API v2.payment.generate_income_statement"
          }
        },
        "required": [
          "income_statement_id"
        ],
        "additionalProperties": false,
        "description": "v2.payment.get_income_statement\nTo query income statement status and provide file link if the income statement is ready to be downloaded.\nAuthorization: Shop; existing bound shop and Seller In House System app. Platform market, enrollment and method permissions still apply."
      },
      "output_schema": {
        "type": "object",
        "properties": {
          "response": {
            "type": "object",
            "properties": {
              "id": {
                "anyOf": [
                  {
                    "type": "integer",
                    "minimum": -9007199254740991,
                    "maximum": 9007199254740991
                  },
                  {
                    "type": "string",
                    "pattern": "^-?(0|[1-9][0-9]{0,18})$"
                  }
                ],
                "x-integer": "int64",
                "description": "The identifier for income statement file request."
              },
              "file_name": {
                "type": "string",
                "description": "Income statement file name."
              },
              "status": {
                "type": "integer",
                "minimum": -2147483648,
                "maximum": 2147483647,
                "description": "STATUS_INVALID = 0; STATUS_PROCESSING = 1; STATUS_DOWNLOADABLE = 2; STATUS_DOWNLOADED = 3; STATUS_FAILED = 4;"
              },
              "generated_time": {
                "anyOf": [
                  {
                    "type": "integer",
                    "minimum": -9007199254740991,
                    "maximum": 9007199254740991
                  },
                  {
                    "type": "string",
                    "pattern": "^-?(0|[1-9][0-9]{0,18})$"
                  }
                ],
                "x-integer": "int64",
                "description": "File generation time."
              },
              "file_link": {
                "type": "string",
                "description": "Link to download income statement file."
              }
            },
            "additionalProperties": true
          },
          "error": {
            "type": "string",
            "description": "Error Code"
          },
          "message": {
            "type": "string",
            "description": "Error Message"
          }
        },
        "additionalProperties": true
      }
    },
